from itertools import combinations

def relation(regions, a, b):
    """Pairwise relation shown by a diagram given as the set of its non-empty regions."""
    a_not_b = any(a in r and b not in r for r in regions)
    b_not_a = any(b in r and a not in r for r in regions)
    both = any(a in r and b in r for r in regions)
    if not both:
        return "disjoint"
    if not a_not_b and not b_not_a:
        return "equal"
    if not a_not_b:
        return f"{a} in {b}"
    if not b_not_a:
        return f"{b} in {a}"
    return "overlap"

def signature(regions, names):
    return {(a, b): relation(regions, a, b) for a, b in combinations(names, 2)}

def best_fit(truth, names, diagrams):
    ok = [k for k, d in diagrams.items() if signature(d, names) == truth]
    assert len(ok) == 1, ok
    return ok[0]

F = lambda *s: frozenset(s)
# Diagrams with circles X, Y, Z, as sets of non-empty regions
diagrams = {
    "A": {F("X"), F("Y"), F("Z")},                                              # three separate circles
    "B": {F("X"), F("X", "Y"), F("X", "Z"), F("X", "Y", "Z"), F("Z")},          # Y inside X, Z cuts both
    "C": {F("X"), F("X", "Y"), F("X", "Y", "Z")},                               # Z in Y in X
    "D": {F("X"), F("Y"), F("Z"), F("X", "Y"), F("Y", "Z"), F("X", "Z"), F("X", "Y", "Z")},  # all overlap
}
# Constructed: Women (X), Mothers (Y), Doctors (Z)
truth = {("X", "Y"): "Y in X", ("X", "Z"): "overlap", ("Y", "Z"): "overlap"}
assert best_fit(truth, "XYZ", diagrams) == "B"
# Constructed: Animals (X), Dogs (Y), Cats (Z): two separate circles inside one
diagrams["E"] = {F("X"), F("X", "Y"), F("X", "Z")}
truth = {("X", "Y"): "Y in X", ("X", "Z"): "Z in X", ("Y", "Z"): "disjoint"}
assert best_fit(truth, "XYZ", diagrams) == "E"
# Constructed: Vehicles (X), Cars (Y), Electric cars (Z): a nested chain
truth = {("X", "Y"): "Y in X", ("X", "Z"): "Z in X", ("Y", "Z"): "Z in Y"}
assert best_fit(truth, "XYZ", diagrams) == "C"
